function textBody(m){return /^\s*</.test(m.row[3])?'['+m.row[2]+']':m.row[3]||'['+m.row[2]+']';}
function affiliations(id){return D.topics.filter(t=>t.sessions.some(s=>id>=s.a&&id<s.b));}
function excerpt(t,n=170){return t.length>n?t.slice(0,n)+'…':t;}
function highlight(t,q){if(!q)return E(t);const i=t.toLowerCase().indexOf(q.toLowerCase());return i<0?E(t):E(t.slice(0,i))+'<mark>'+E(t.slice(i,i+q.length))+'</mark>'+E(t.slice(i+q.length));}
function search(){
app.innerHTML=heading('CONVERSATION RETRIEVAL','对话语料检索','将关键词、发言者、日期与话题组合，找到讨论发生的原始位置。')+'<div class="tabs"><button class="active">关键词搜索</button><button disabled title="阶段三确认本地模型与索引后接入">语义搜索 · 待接入</button></div><div class="toolbar"><input id="query" type="search" placeholder="搜索原话，例如：佛、五行、女权……" aria-label="搜索聊天内容" value="'+E(searchQuery)+'"><button class="btn primary" id="search-button">搜索全部消息</button></div><div class="search-filters"><label>发言者<select id="filter-person"><option value="">双方</option>'+[0,1].map(p=>'<option value="'+p+'" '+(String(p)===searchSpeaker?'selected':'')+'>'+E(name(p))+'</option>').join('')+'</select></label><label>起始日期<input type="date" id="filter-from" value="'+searchFrom+'"></label><label>结束日期<input type="date" id="filter-to" value="'+searchTo+'"></label><label>所属话题<select id="filter-topic"><option value="">全部话题</option>'+D.topics.map(t=>'<option value="'+t.id+'" '+(searchTopic===t.id?'selected':'')+'>'+E(excerpt(t.title,18))+'</option>').join('')+'</select></label></div><div class="panel"><div class="panel-heading"><h3>搜索结果</h3><span id="result-count" class="sample-size"></span></div><div id="results"></div></div><p class="chart-note">当前搜索完整本地快照中的 '+F(D.messages.length)+' 条消息；结果与话题详情共用同一个原文侧栏。</p>';
const update=()=>{searchQuery=$('query').value.trim();searchSpeaker=$('filter-person').value;searchFrom=$('filter-from').value;searchTo=$('filter-to').value;searchTopic=$('filter-topic').value;searchLimit=20;results();};$('search-button').onclick=update;$('query').onkeydown=e=>{if(e.key==='Enter')update();};['filter-person','filter-from','filter-to','filter-topic'].forEach(id=>$(id).onchange=update);results();
}
function results(){
const matched=D.messages.filter(m=>['text','reply'].includes(m.row[2])&&textBody(m).toLowerCase().includes(searchQuery.toLowerCase())&&(searchSpeaker===''||person(m)===+searchSpeaker)&&(!searchFrom||m.row[0].slice(0,10)>=searchFrom)&&(!searchTo||m.row[0].slice(0,10)<=searchTo)&&(!searchTopic||affiliations(m.id).some(t=>t.id===searchTopic)));
$('result-count').textContent=matched.length+' 条命中 / '+F(D.messages.length)+' 条样例';
$('results').innerHTML=matched.length?matched.slice(0,searchLimit).map(m=>{const p=person(m),topics=affiliations(m.id),prev=messagesById.get(m.id-1);return '<article class="result"><div class="result-meta"><span class="'+(p?'s':'g')+'">'+E(name(p))+'</span><time>'+m.row[0].replace('T',' ').replace('+08:00','')+'</time><span>'+E(topics[0]?.category||'片段前后文')+'</span></div>'+(prev?'<div class="result-context">前文：'+E(excerpt(textBody(prev),100))+'</div>':'')+'<div class="result-content">'+highlight(excerpt(textBody(m),360),searchQuery)+'</div><div class="inline-actions"><button class="btn" data-context="'+m.id+'">查看完整上下文 →</button>'+(topics[0]?'<a class="quiet-link" href="#topic/'+topics[0].id+'">'+E(excerpt(topics[0].title,25))+'</a>':'')+'</div></article>';}).join('')+(matched.length>searchLimit?'<button class="btn" id="more-results">再显示 20 条</button>':''):'<div class="empty">未在本阶段样例中找到匹配内容。可尝试“佛”“五行”或放宽筛选条件。</div>';
if($('more-results'))$('more-results').onclick=()=>{searchLimit+=20;results();};
}
