let iconJob=0;
async function uploadIcon(file){
if(!file)return;const job=++iconJob;
const status=t=>{if($('icon-status'))$('icon-status').textContent=t;};
if(file.size>4*1024*1024){status('图片超过 4 MB，请选择较小的图标文件。');return;}
if(!/\.(png|jpe?g|webp|svg|ico)$/i.test(file.name)&&!['image/png','image/jpeg','image/webp','image/svg+xml','image/x-icon','image/vnd.microsoft.icon'].includes(file.type)){status('请选择 PNG、JPG、WebP、SVG 或 ICO 图片。');return;}
status('正在读取图标…');let url;
try{
url=URL.createObjectURL(file);const image=new Image();
await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('图片无法读取，请换一个有效的图片文件。'));image.src=url;});
if(job!==iconJob)return;
if(!image.naturalWidth||!image.naturalHeight)throw new Error('图片尺寸无效，请重新选择。');
const canvas=document.createElement('canvas');canvas.width=canvas.height=128;const context=canvas.getContext('2d');if(!context)throw new Error('浏览器不支持图标转换，请使用其他浏览器打开。');
const scale=Math.min(128/image.naturalWidth,128/image.naturalHeight),w=image.naturalWidth*scale,h=image.naturalHeight*scale;context.drawImage(image,(128-w)/2,(128-h)/2,w,h);
const data=canvas.toDataURL('image/png');if(!preferences.isIcon(data))throw new Error('图标转换失败，请尝试另一张图片。');
settings.icon=data;applyIcon();status(persist()?'图标已保存，左上角与浏览器标签页已同步替换。':'图标已替换；浏览器未允许保存，刷新后会恢复。');
}catch(error){if(job===iconJob)status(error.message||'图标读取失败，请重试。');}finally{if(url)URL.revokeObjectURL(url);}
}
function viewButtons(){return [['cards','卡片视图'],['list','列表视图']].map(([key,label])=>'<button class="btn '+(settings.topicView===key?'selected':'')+'" data-topic-view="'+key+'" aria-pressed="'+(settings.topicView===key)+'">'+label+'</button>').join('');}
function openContext(from,to,title,focus=null){const list=D.messages.filter(m=>m.id>=from&&m.id<to),dialog=$('conversation-dialog');$('dialog-content').innerHTML='<div class="dialog-head"><div><div class="eyebrow">CONVERSATION DETAIL / SOURCE</div><h2 id="conversation-title">对话详情</h2><p>来源：'+E(title)+'<br>原始时间 · 双方发言 · 片段前后文</p></div><button class="btn" id="close-dialog" aria-label="返回来源页面">关闭 ×</button></div><div class="dialog-messages">'+list.map(m=>{const p=person(m);return '<article class="message '+(p===1?'si':p===null?'system':'')+(m.id===focus?' highlight':'')+'"'+(m.id===focus?' id="focused-message"':'')+'><div class="message-meta"><b>'+E(p===null?'系统':name(p))+'</b><time>'+m.row[0].replace('T',' ').replace('+08:00','')+'</time><span>'+E(m.row[2])+'</span></div><div class="message-body">'+E(textBody(m))+'</div></article>';}).join('')+'</div><div class="dialog-foot">当前载入 '+list.length+' 条样例上下文。图片、语音等保留类型占位，关闭后回到原来的页面与筛选。</div>';$('close-dialog').onclick=()=>dialog.close();dialog.showModal();if(focus!==null)$('focused-message')?.scrollIntoView({block:'center'});}
const serviceCall=async(pathname,options={})=>{const response=await fetch(pathname,{cache:'no-store',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||('HTTP '+response.status));return data;};
const serviceTime=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚无记录';
const serviceJobName=type=>type==='wechat'?'微信源更新':type==='analysis'?'统计发布':'网站导入';
const serviceJobState=status=>({queued:'等待执行',running:'正在执行',succeeded:'已完成',failed:'失败'}[status]||status);
