function mountUpdateService(){
 const panels=[...document.querySelectorAll('.panel')],current=panels.find(p=>p.querySelector('h3')?.textContent.includes('当前聊天数据')),scheduled=panels.find(p=>p.querySelector('h3')?.textContent.includes('周期更新')),contract=panels.find(p=>p.querySelector('h3')?.textContent.includes('接口契约预览'));
 if(!current||!scheduled)return;
 if(contract){const badge=contract.querySelector('.sample-size'),note=contract.querySelector('.footnote');if(badge)badge.textContent='阶段三 · 已接入';if(note)note.textContent='导入、任务状态与定时策略已接入本地服务；语义搜索仍需单独确认模型与索引方案。';}
 current.innerHTML='<div class="panel-heading"><div><h3>当前聊天数据</h3><div class="subtitle">CURRENT DATASET · PUBLISHED VERSION</div></div><span class="sample-size" id="dataset-version">连接中</span></div><div id="dataset-runtime" class="service-loading" aria-live="polite"><i></i><i></i><i></i></div><div class="inline-actions"><button class="btn primary" id="run-import">检查并导入更新</button><button class="btn" id="run-analysis">重新发布统计</button></div><p id="import-status" class="preview-status" role="status">服务只读取已配置的本地导出目录；失败时继续使用上一成功版本。</p>';
 scheduled.innerHTML='<div class="panel-heading"><div><h3>周期更新</h3><div class="subtitle">SCHEDULED IMPORTS · LOCAL SERVICE</div></div><span class="status-label" id="policy-state">读取中</span></div><label class="field" for="update-source">本地导出来源<input id="update-source" type="text" spellcheck="false" autocomplete="off"></label><div class="update-policy-row"><label class="field" for="update-time">每日检查时间<input id="update-time" type="time" value="04:00"></label><label class="toggle-field"><input id="update-enabled" type="checkbox"><span>启用周期更新</span></label><label class="toggle-field"><input id="update-catchup" type="checkbox"><span>启动后补查漏跑</span></label></div><div class="inline-actions"><button class="btn primary" id="save-policy">保存更新策略</button></div><p id="policy-status" class="preview-status" role="status">时区固定为 Asia/Shanghai；电脑关闭时不会执行。</p>';
 scheduled.parentElement.insertAdjacentHTML('afterend','<section class="panel update-log"><div class="panel-heading"><div><h3>更新任务记录</h3><div class="subtitle">IMPORT & ANALYSIS RUNS</div></div><button class="btn text" id="refresh-jobs">刷新状态</button></div><div id="job-list" class="job-list" aria-live="polite"><div class="service-loading"><i></i><i></i></div></div></section>');
 if(typeof window.fetch!=='function'){$('dataset-version').textContent='离线快照';$('dataset-runtime').className='empty compact';$('dataset-runtime').textContent='当前环境未连接本地更新服务。';$('policy-state').textContent='服务离线';['run-import','run-analysis','save-policy','refresh-jobs'].forEach(id=>$(id).disabled=true);return;}
 const setBusy=(button,busy,label)=>{button.disabled=busy;button.dataset.label??=button.textContent;button.textContent=busy?label:button.dataset.label;};
 const renderDataset=data=>{$('dataset-version').textContent=data.dataset_version;$('dataset-runtime').className='';$('dataset-runtime').innerHTML='<dl class="definition"><dt>发布版本</dt><dd>'+E(data.dataset_version)+'</dd><dt>消息时间覆盖</dt><dd>'+E(data.start)+' — '+E(data.end)+'</dd><dt>原始记录</dt><dd>'+F(data.message_count)+' 条</dd><dt>非系统消息</dt><dd>'+F(data.non_system_messages)+' 条</dd><dt>整理话题</dt><dd>'+F(data.topic_count)+' 个 · 覆盖至 '+E(data.topic_coverage_end||data.end)+'</dd><dt>最后导入</dt><dd>'+serviceTime(data.last_import_at)+'</dd><dt>当前发布</dt><dd>'+serviceTime(data.published_at)+'</dd></dl>';};
 const renderPolicy=data=>{$('update-source').value=data.source_path||'';$('update-time').value=data.time||'04:00';$('update-enabled').checked=Boolean(data.enabled);$('update-catchup').checked=data.catch_up!==false;$('policy-state').textContent=data.enabled?'已启用':'未启用';$('policy-state').classList.toggle('active',Boolean(data.enabled));};
 const renderJobs=data=>{$('job-list').innerHTML=data.items.length?data.items.map(job=>'<article class="job-row"><div><b>'+serviceJobName(job.type)+'</b><span>'+E(job.result?.dry_run?'试运行':job.trigger==='scheduled'?'定时任务':'手动任务')+' · '+serviceTime(job.created_at)+'</span></div><div class="job-result">'+(job.result?'<span>新增 '+F(job.result.inserted||0)+'</span><span>重复 '+F(job.result.duplicates||0)+'</span><span>'+E(job.result.published_version||job.base_version)+'</span>':'<span>'+E(job.error||'等待结果')+'</span>')+'</div><strong class="job-state '+E(job.status)+'">'+serviceJobState(job.status)+'</strong></article>').join(''):'<div class="empty compact">尚无更新任务。首次检查会在这里记录新增、重复和发布版本。</div>';};
 const refresh=async()=>{try{const [dataset,policyData,jobData]=await Promise.all([serviceCall('/api/v1/datasets/current'),serviceCall('/api/v1/update-policy'),serviceCall('/api/v1/jobs')]);renderDataset(dataset);renderPolicy(policyData);renderJobs(jobData);$('data-source-label').textContent='本地更新服务已连接 · '+dataset.dataset_version;}catch(error){$('dataset-version').textContent='离线快照';$('dataset-runtime').className='empty compact';$('dataset-runtime').textContent='更新服务不可用：'+error.message;$('policy-state').textContent='服务离线';$('run-import').disabled=true;$('run-analysis').disabled=true;$('save-policy').disabled=true;$('data-source-label').textContent='当前使用静态快照';}};
 const poll=async(jobId)=>{for(let attempt=0;attempt<90;attempt++){const job=await serviceCall('/api/v1/jobs/'+encodeURIComponent(jobId));if(!['queued','running'].includes(job.status)){await refresh();const status=$('import-status');status.textContent=job.status==='succeeded'?(job.result?.message||'任务完成。'):'任务失败：'+job.error;if(job.status==='succeeded'&&job.result?.changed){status.insertAdjacentHTML('beforeend',' <button class="btn text" id="apply-data-version">刷新并应用新版本</button>');$('apply-data-version').onclick=()=>location.reload();}return job;}await new Promise(resolve=>setTimeout(resolve,800));}throw new Error('任务仍在运行，请稍后刷新状态。');};
 $('run-import').onclick=async()=>{const button=$('run-import');setBusy(button,true,'正在检查…');$('import-status').textContent='正在校验来源、去重并准备发布版本。';try{const job=await serviceCall('/api/v1/imports',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID?.()||('manual-'+Date.now())},body:JSON.stringify({source_path:$('update-source').value,trigger:'manual'})});await poll(job.job_id);}catch(error){$('import-status').textContent='导入失败：'+error.message;}finally{setBusy(button,false);}};
 $('run-analysis').onclick=async()=>{const button=$('run-analysis');setBusy(button,true,'正在发布…');$('import-status').textContent='正在校验当前统计快照。';try{const job=await serviceCall('/api/v1/analysis-runs',{method:'POST',headers:{'Idempotency-Key':'analysis-'+Date.now()},body:'{}'});await poll(job.job_id);}catch(error){$('import-status').textContent='统计发布失败：'+error.message;}finally{setBusy(button,false);}};
 $('save-policy').onclick=async()=>{const button=$('save-policy');setBusy(button,true,'正在保存…');try{const saved=await serviceCall('/api/v1/update-policy',{method:'PUT',body:JSON.stringify({source_path:$('update-source').value,time:$('update-time').value,enabled:$('update-enabled').checked,catch_up:$('update-catchup').checked})});renderPolicy(saved);$('policy-status').textContent='更新策略已保存。下一次检查按本地服务运行时间执行。';}catch(error){$('policy-status').textContent='保存失败：'+error.message;}finally{setBusy(button,false);}};
 $('refresh-jobs').onclick=refresh;refresh();
}
